{
  "file_name": "GearShape",
  "hlsl_code": "void GearShape_float(float2 UV, float Size, float TeethCount, float ToothDepth, float HoleRadius, float4 GearColor, float4 HoleColor, out float4 outColor) {
    // PLAN:
    // 1) Center UVs and convert to polar coordinates (angle, radius).
    // 2) Generate a gear tooth pattern using a clamped/smoothed cosine of the angle.
    // 3) Create the Gear Body SDF by modulating the radius with the tooth pattern.
    // 4) Create the Hole SDF as a simple circle in the center.
    // 5) Define disjoint masks for the "Gear Ring" (Body minus Hole) and the "Hole".
    // 6) Combine colors using straight alpha composition to ensure correct blending in Unity.

    #ifndef PI
    #define PI 3.14159265359
    #endif

    float2 p = UV - 0.5;
    float r = length(p);
    float angle = atan2(p.y, p.x);

    // --- Gear Body SDF ---
    // N: Number of teeth
    float N = floor(max(3.0, TeethCount));

    // Tooth shape modulation
    // cos(angle * N) gives N lobes.
    // smoothstep sharpens the sine wave into a rounded-trapezoid/cog shape.
    // Range [-1, 1] -> smoothstep -> [0, 1] modulation.
    float toothSignal = cos(angle * N);
    float toothMod = smoothstep(-0.2, 0.2, toothSignal);

    // Effective radius: Base Size + extra depth for teeth
    float currentGearRadius = Size + ToothDepth * toothMod;
    float dGear = r - currentGearRadius;

    // --- Hole SDF ---
    float dHole = r - HoleRadius;

    // --- Masks & Anti-aliasing ---
    // We define the "Ring" as the Gear Body EXCLUDING the Hole.
    // Ideally, we want dRing = max(dGear, -dHole) for a boolean subtract,
    // but we treat them as disjoint render layers for coloring.

    // Calculate intersection SDF for the gear body proper (excluding hole)
    float dRing = max(dGear, -dHole);

    float aaRing = fwidth(dRing);
    float aaHole = fwidth(dHole);

    // Mask for the solid gear material (ring)
    // d < 0 is inside. smoothstep(aa, -aa, d) gives 1 inside, 0 outside.
    float maskRing = smoothstep(aaRing, -aaRing, dRing);

    // Mask for the hole area
    float maskHole = smoothstep(aaHole, -aaHole, dHole);

    // --- Coloring ---
    // We combine the colors using weighted averaging to produce a Straight Alpha output.
    // This ensures that when Unity multiplies RGB by Alpha later, the result is a correct mix.

    float totalWeight = maskRing + maskHole;

    // Weighted average of the RGB colors based on coverage
    // If maskRing is 1, we get GearColor. If maskHole is 1, we get HoleColor.
    // At the boundary, we blend.
    float3 finalRGB = (GearColor.rgb * maskRing + HoleColor.rgb * maskHole) / max(totalWeight, 0.0001);

    // Weighted sum of Alphas
    // If disjoint, this is just the sum.
    float finalAlpha = GearColor.a * maskRing + HoleColor.a * maskHole;

    outColor = float4(finalRGB, finalAlpha);
}",
