  "file_name": "CrescentMoonShape",
  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

// SDF for a circle at origin
float sdCircle(float2 p, float r) {
    return length(p) - r;
}

// Main Function: Crescent Moon Shape
// A crescent moon created by subtracting one circle from another.
// Features adjustable size, thickness, rotation, and auto-centering.
void CrescentMoonShape_float(float2 UV, float Size, float Thickness, float Rotation, float2 Center, float4 Color, out float4 outColor) {
    // PLAN:
    // 1) Center and Rotate UV coordinates.
    // 2) Determine offsets for outer and inner circles to keep the crescent centered.
    // 3) Calculate SDFs for both circles.
    // 4) Subtract inner from outer (max(outer, -inner)).
    // 5) Apply smoothstep AA and output color.

    // 1) Center and Rotate
    float2 p = UV - Center;
    float cosR = cos(Rotation);
    float sinR = sin(Rotation);
    // Rotate p by -Rotation so the shape appears rotated by +Rotation
    p = float2(cosR * p.x + sinR * p.y, -sinR * p.x + cosR * p.y);

    // 2) Determine Offsets for Centering
    // To keep the visual mass centered at (0,0), we adjust the circle positions.
    // With Outer at (0,0) and Inner shifted Left by Thickness, the crescent forms on the Right.
    // Its X-bounds would be [Size - Thickness, Size]. Midpoint is Size - Thickness/2.
    // We shift both circles Left by this midpoint amount to center the crescent at 0.
    float centeringOffset = Size - Thickness * 0.5;

    float2 centerOuter = float2(-centeringOffset, 0.0);
    // Inner circle is shifted left by 'Thickness' relative to Outer
    float2 centerInner = float2(-Thickness - centeringOffset, 0.0);

    // 3) Calculate SDFs
    // We use the same radius (Size) for both to get sharp tips
    float dOuter = sdCircle(p - centerOuter, Size);
    float dInner = sdCircle(p - centerInner, Size);

    // 4) Subtract Inner from Outer (Intersection of Outer and NOT Inner)
    // Standard SDF boolean subtract: max(d1, -d2)
    float dist = max(dOuter, -dInner);

    // 5) Anti-aliasing and Color Output
    float aa = fwidth(dist);
    aa = max(aa, 0.001); // Safety clamp for AA width

    float edge = smoothstep(aa, -aa, dist);

    // Output premultiplied RGB with edge as alpha mask
    // This ensures correct blending in standard transparent setups
    outColor = float4(Color.rgb * edge, edge);
}",
