{
  "file_name": "StylizedFlower",
  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

// Helper: Approximate Signed Distance to Ellipse
// p: point relative to ellipse center
// r: radii (half-width, half-height)
// Returns approx Euclidean distance (negative inside, positive outside)
inline float sdEllipse(float2 p, float2 r) {
    // Prevent division by zero
    float rx = max(r.x, 0.0001);
    float ry = max(r.y, 0.0001);

    // Implicit equation: x^2/a^2 + y^2/b^2 - 1
    float val = (p.x * p.x) / (rx * rx) + (p.y * p.y) / (ry * ry) - 1.0;

    // Gradient magnitude: 2 * sqrt( x^2/a^4 + y^2/b^4 )
    float grad = 2.0 * sqrt( (p.x * p.x) / (rx * rx * rx * rx) + (p.y * p.y) / (ry * ry * ry * ry) );

    // Distance ~= Value / Gradient
    return val / max(grad, 0.0001);
}

// Helper: Alpha Blending (Src Over Dst)
// Assumes straight alpha inputs (RGB, A) and returns straight alpha
inline float4 blendOver(float4 src, float4 dst) {
    float outA = src.a + dst.a * (1.0 - src.a);
    float3 outRGB = (src.rgb * src.a + dst.rgb * dst.a * (1.0 - src.a)) / max(outA, 0.0001);
    return float4(outRGB, outA);
}

void StylizedFlower_float(float2 UV, float2 Center, float Rotation, float PetalCount, float PetalLength, float PetalWidth, float CenterRadius, float4 PetalColor, float4 CenterColor, out float4 outColor) {
    // PLAN:
    // 1) Recenter UV coordinates to 'Center'.
    // 2) Apply global Rotation to the coordinates.
    // 3) Calculate SDF for the central disk (pistil).
    // 4) Convert to polar coordinates and apply angular domain repetition for petals.
    // 5) Define a single petal as an ellipse offset from the center.
    // 6) Compute SDFs, apply smoothstep for anti-aliasing masks.
    // 7) Composite the Center color over the Petal color using alpha blending.

    // 1) Center UV
    float2 p = UV - Center;

    // 2) Apply Rotation
    float cosR = cos(Rotation);
    float sinR = sin(Rotation);
    p = float2(p.x * cosR - p.y * sinR, p.x * sinR + p.y * cosR);

    // 3) Center Disk SDF
    float dCenter = length(p) - CenterRadius;

    // 4) Polar Coordinates & Domain Repetition
    float r = length(p);
    float a = atan2(p.y, p.x);

    // Number of petals (ensure at least 1 to avoid divide by zero)
    float n = max(1.0, floor(PetalCount));
    float sectorAngle = (2.0 * PI) / n;

    // Repeat angle: Align sector center to x-axis
    // Add PI ensures positive range for reliable fmod, shift back by half sector
    float an = sectorAngle;
    float he = an * 0.5;
    float aLocal = fmod(a + PI + he, an) - he;

    // Reconstruct cartesian coordinates in the local repeated sector
    // The petal lies along the local X-axis
    float2 pPolar = float2(cos(aLocal), sin(aLocal)) * r;

    // 5) Petal SDF (Ellipse)
    // Calculate positioning to attach petal to the center radius
    float pLen = PetalLength * 0.5;
    float pWid = PetalWidth * 0.5;
    // Offset the petal so it starts near the center radius
    float2 petalOffset = float2(CenterRadius + pLen - (CenterRadius * 0.1), 0.0);
    float2 petalSize = float2(pLen, pWid);

    float dPetal = sdEllipse(pPolar - petalOffset, petalSize);

    // 6) Anti-aliasing Masks
    // Use fwidth for consistent edge softness regardless of scale
    float aaPetal = fwidth(dPetal);
    float aaCenter = fwidth(dCenter);
    // Fallback if fwidth is zero (e.g. constant inputs)
    if (aaPetal <= 0.0) aaPetal = 0.001;
    if (aaCenter <= 0.0) aaCenter = 0.001;

    // Smoothstep: SDF < 0 is inside (1.0), SDF > 0 is outside (0.0)
    float maskPetal = 1.0 - smoothstep(0.0, aaPetal, dPetal);
    float maskCenter = 1.0 - smoothstep(0.0, aaCenter, dCenter);

    // 7) Composition
    // Create RGBA layers based on masks
    float4 layerPetal = float4(PetalColor.rgb, PetalColor.a * maskPetal);
    float4 layerCenter = float4(CenterColor.rgb, CenterColor.a * maskCenter);

    // Blend Center OVER Petal (Center acts as source, Petal as destination)
    outColor = blendOver(layerCenter, layerPetal);
}",
