{
  "file_name": "SpiralShape",
  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

void SpiralShape_float(float2 UV, float Turns, float Thickness, float2 Center, float Rotation, float4 Color, out float4 outColor) {
    // PLAN:
    // 1) User Request: Spiral shape growing outward from the center.
    // 2) Center and rotate UV coordinates.
    // 3) Convert to polar coordinates (radius r, angle a).
    // 4) Calculate spiral domain value S = r * Turns - a.
    // 5) Compute distance to nearest spiral arm in "turn space".
    // 6) Use analytical gradient for AA to avoid atan2 seam artifacts.
    // 7) Apply thickness and color with alpha blending.

    float2 p = UV - Center;

    // Rotate p
    float cosRot = cos(Rotation);
    float sinRot = sin(Rotation);
    p = float2(cosRot * p.x - sinRot * p.y, sinRot * p.x + cosRot * p.y);

    float r = length(p);
    // Angle in [0, 1] range. Adding 0.5/PI factor normalization.
    float a = atan2(p.y, p.x) / (2.0 * PI);

    // Spiral domain function: S increases by 1 for every full turn (r increases by 1/Turns)
    // We subtract 'a' so that increasing angle (CCW) compensates for increasing radius.
    float S = r * Turns - a;

    // Triangle wave to measure distance to the "center" of the spiral arm
    // frac(S + 0.5) shifts domain so integer values are at 0.5 in 0..1 range
    // abs( ... - 0.5) maps it to 0..0.5, where 0 is the center of the arm
    float distToArm = abs(frac(S + 0.5) - 0.5);

    // Analytic AA width calculation
    // Gradient magnitude of S w.r.t. UV space: |grad S| = sqrt( (dS/dr)^2 + (1/r * dS/dphi)^2 )
    // dS/dr = Turns
    // dS/dphi = -1 / (2*PI)
    // Avoid division by zero with max(r, small_epsilon)
    float dS = sqrt(Turns * Turns + 1.0 / (4.0 * PI * PI * max(r * r, 0.000001)));

    // Pixel size estimate using fwidth of radius (approx isotropic)
    float aa = dS * fwidth(r) * 1.5;

    // Threshold for thickness (Thickness is 0..1 fraction of arm spacing)
    float halfThick = Thickness * 0.5;

    // Signed distance: negative = inside line, positive = outside
    float dist = distToArm - halfThick;

    // Smoothstep for AA mask (1.0 inside, 0.0 outside)
    float mask = smoothstep(aa, -aa, dist);

    // Fade out center singularity to prevent moire/aliasing at r=0
    mask *= smoothstep(0.0, 0.01 / max(abs(Turns), 1.0), r);

    // Output with alpha handling
    outColor = float4(Color.rgb * mask, Color.a * mask);
}",
