{
  "file_name": "SnowflakeShape",
  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

// Distance to a line segment
float sdSegment_Snowflake(float2 p, float2 a, float2 b) {
    float2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

void SnowflakeShape_float(float2 UV, float Size, float Branches, float Thickness, float4 Color, out float4 outColor) {
    // PLAN: Symmetric snowflake with repeating branches
    // 1) Center UVs and handle polar repetition (folding space) for N-way symmetry.
    // 2) Align the active sector to the X-axis for easier construction.
    // 3) Construct one arm using a trunk segment.
    // 4) Add repeating side branches (V-shapes) using a loop and segment SDFs.
    // 5) Combine distances, apply thickness, and anti-alias.

    float2 p = UV - 0.5;

    // --- 1 & 2: Polar Repetition & Alignment ---
    // Ensure at least 3 branches to form a polygon/star shape
    float n = max(3.0, round(Branches));
    float sectorAngle = (2.0 * PI) / n;

    // Get current angle and snap to the nearest sector center
    float ang = atan2(p.y, p.x);
    float id = floor((ang + PI) / sectorAngle);
    float centerAng = id * sectorAngle + sectorAngle * 0.5 - PI;

    // Rotate p by -centerAng to align the arm with the +X axis
    // Standard 2D rotation: x' = x*c - y*s, y' = x*s + y*c
    float c = cos(-centerAng);
    float s = sin(-centerAng);
    float2 rotP = float2(c * p.x - s * p.y, s * p.x + c * p.y);

